    SourceDedupPartialDependencyPermitTest f;GenerationJdbcStoreTest db;NewsValueSourcePlanPreparationService service;FrozenSourceStagePlanService plans;FrozenSourceDedupDependency dependency;SourceDedupPartialDependencyPermitService.Captured permit;Clock clock;String intent;boolean allowed=true;int settingsReads;List<String> blocked=List.of();
